use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::{Constraint, FieldSchema, FieldType, PluginSchema};
use parking_lot::Mutex;
use serde::{Deserialize, Serialize};
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::collections::{HashMap, HashSet};
use std::os::unix::net::UnixListener;
use std::path::Path;
use std::sync::Arc;
use tracing::{info, warn};

/// The single active-schema catalog in shared memory. Every plugin reads its
/// own slice by name from this one file — there is no per-plugin shm file and
/// no diff loop. The schema's declared state IS the desired state.
const SHM_SCHEMA_PATH: &str = "/dev/shm/live-schema.json";

fn default_protocol() -> String {
    "grpc".to_string()
}

/// A configured unix-domain socket endpoint.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct SocketEndpoint {
    /// Filesystem path to the socket (e.g. `/run/qdrant.sock`).
    pub path: String,
    /// Local TCP port xray listens on and proxies into this socket.
    #[schemars(range(min = 1, max = 65535))]
    pub port: u16,
    /// Transport protocol carried over the socket (`"grpc"`, `"jsonrpc"`, …).
    #[serde(default = "default_protocol")]
    pub protocol: String,
    /// Human-readable service label used as the xray outbound tag.
    #[serde(default)]
    pub label: String,
}

/// Runtime state: all declared socket endpoints.
#[derive(Debug, Clone, Serialize, Deserialize, Default, schemars::JsonSchema)]
pub struct UnixSocketState {
    /// Declared unix socket endpoints visible to internal services.
    pub sockets: Vec<SocketEndpoint>,
}

/// Canonical `unix_socket` schema, **derived** from the structs via schemars
/// (see [`super::schemars_adapter`]). `port` bounds, field descriptions (from
/// doc comments) and `required` flags all come from the type — the struct is
/// the single source of truth. The frozen hand-rolled `unix_socket_schema()`
/// (test-only) guards this against drift via `derived_schema_matches_hand_rolled`.
pub fn unix_socket_schema_derived() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(UnixSocketState))
        .expect("schemars schema serializes to JSON");
    super::schemars_adapter::plugin_schema_from_json(
        "unix_socket",
        "1.0.0",
        "Unix domain socket endpoints proxied into xray outbounds",
        &root,
    )
}

pub struct UnixSocketPlugin {
    /// Live listeners keyed by socket path. Holding the `UnixListener` keeps the
    /// socket bound for the lifetime of the plugin; dropping it tears it down.
    active: Arc<Mutex<HashMap<String, UnixListener>>>,
}

impl UnixSocketPlugin {
    pub fn new() -> Self {
        Self {
            active: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    /// Read this plugin's desired socket set straight from the single active
    /// schema catalog in shared memory (zero-copy 1:1). The catalog is keyed by
    /// plugin name and each entry carries the schema-declared state.
    fn read_desired() -> UnixSocketState {
        let Ok(mut bytes) = std::fs::read(SHM_SCHEMA_PATH) else {
            return UnixSocketState::default();
        };
        let Ok(catalog) = simd_json::to_owned_value(&mut bytes) else {
            return UnixSocketState::default();
        };
        let Some(state) = catalog
            .get("unix_socket")
            .and_then(|versions| versions.as_array())
            .and_then(|versions| versions.last())
            .and_then(|schema| schema.get("example"))
        else {
            return UnixSocketState::default();
        };
        simd_json::serde::from_owned_value::<UnixSocketState>(state.clone()).unwrap_or_default()
    }

    /// Bind a single endpoint, replacing any stale socket file. Returns `true`
    /// when a new listener was created.
    fn ensure_bound(
        active: &mut HashMap<String, UnixListener>,
        endpoint: &SocketEndpoint,
    ) -> Result<bool> {
        if active.contains_key(&endpoint.path) {
            return Ok(false);
        }
        if let Some(parent) = Path::new(&endpoint.path).parent() {
            std::fs::create_dir_all(parent)?;
        }
        if Path::new(&endpoint.path).exists() {
            std::fs::remove_file(&endpoint.path)?;
        }
        let listener = UnixListener::bind(&endpoint.path)?;
        listener.set_nonblocking(true)?;
        active.insert(endpoint.path.clone(), listener);
        info!(
            socket = %endpoint.path,
            port = endpoint.port,
            protocol = %endpoint.protocol,
            "bound unix socket endpoint"
        );
        Ok(true)
    }

    /// Drop a listener and unlink its socket file. Returns `true` when removed.
    fn unbind(active: &mut HashMap<String, UnixListener>, path: &str) -> bool {
        if active.remove(path).is_some() {
            if let Err(error) = std::fs::remove_file(path) {
                warn!(socket = %path, %error, "failed to unlink unix socket file");
            }
            true
        } else {
            false
        }
    }

    /// Reconcile the live listeners to exactly the supplied desired set.
    fn reconcile(&self, desired: &UnixSocketState) -> ApplyResult {
        let mut active = self.active.lock();
        let mut changes_applied = Vec::new();
        let mut errors = Vec::new();

        let wanted: HashSet<String> = desired.sockets.iter().map(|s| s.path.clone()).collect();

        for endpoint in &desired.sockets {
            match Self::ensure_bound(&mut active, endpoint) {
                Ok(true) => changes_applied.push(format!(
                    "created socket {} (port {}, {})",
                    endpoint.path, endpoint.port, endpoint.protocol
                )),
                Ok(false) => {}
                Err(error) => errors.push(format!(
                    "failed to create socket {}: {}",
                    endpoint.path, error
                )),
            }
        }

        let stale: Vec<String> = active
            .keys()
            .filter(|path| !wanted.contains(*path))
            .cloned()
            .collect();
        for path in stale {
            if Self::unbind(&mut active, &path) {
                changes_applied.push(format!("removed socket {}", path));
            }
        }

        ApplyResult {
            success: errors.is_empty(),
            changes_applied,
            errors,
            checkpoint: None,
        }
    }
}

impl Default for UnixSocketPlugin {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl StatePlugin for UnixSocketPlugin {
    fn name(&self) -> &str {
        "unix_socket"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<op_state_store::PluginSchema> {
        Some(unix_socket_schema_derived())
    }

    async fn query_current_state(&self) -> Result<Value> {
        // The schema-declared desired state in the active-schema catalog is the
        // current state (1:1, zero-copy). Fall back to whatever is live-bound.
        let mut state = Self::read_desired();
        if state.sockets.is_empty() {
            let active = self.active.lock();
            state.sockets = active
                .keys()
                .map(|path| SocketEndpoint {
                    path: path.clone(),
                    port: 0,
                    protocol: default_protocol(),
                    label: String::new(),
                })
                .collect();
        }
        Ok(simd_json::serde::to_owned_value(state)?)
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        // No diff loop: the schema-declared state is authoritative and applied
        // wholesale by `apply_state`.
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: "schema".to_string(),
                desired_hash: "schema".to_string(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        // Reconcile the live unix sockets to exactly the schema-declared set.
        let desired = Self::read_desired();
        Ok(self.reconcile(&desired))
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        let desired = Self::read_desired();
        let active = self.active.lock();
        let satisfied = desired.sockets.iter().all(|endpoint| {
            active.contains_key(&endpoint.path) && Path::new(&endpoint.path).exists()
        });
        Ok(satisfied)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(Self::read_desired())?,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, checkpoint: &Checkpoint) -> Result<()> {
        let snapshot = simd_json::serde::from_owned_value::<UnixSocketState>(
            checkpoint.state_snapshot.clone(),
        )
        .unwrap_or_default();
        self.reconcile(&snapshot);
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: true,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn endpoint(dir: &std::path::Path, name: &str, port: u16) -> SocketEndpoint {
        SocketEndpoint {
            path: dir.join(name).to_string_lossy().into_owned(),
            port,
            protocol: "grpc".to_string(),
            label: name.to_string(),
        }
    }

    fn sockets_object(s: &PluginSchema) -> &HashMap<String, FieldSchema> {
        match &s.fields.get("sockets").expect("sockets field").field_type {
            FieldType::Array(inner) => match inner.as_ref() {
                FieldType::Object(m) => m,
                other => panic!("items not object: {other:?}"),
            },
            other => panic!("sockets not array: {other:?}"),
        }
    }

    /// The schemars-derived schema must match the hand-rolled one field-for-field.
    #[test]
    fn derived_schema_matches_hand_rolled() {
        let hand = unix_socket_schema();
        let derived = unix_socket_schema_derived();

        assert_eq!(derived.name, hand.name);
        assert_eq!(derived.version, hand.version);

        let hp = sockets_object(&hand);
        let dp = sockets_object(&derived);

        let mut hk: Vec<_> = hp.keys().cloned().collect();
        let mut dk: Vec<_> = dp.keys().cloned().collect();
        hk.sort();
        dk.sort();
        assert_eq!(dk, hk, "derived inner fields must match hand-rolled");

        // port: Integer with Min+Max bounds, derived from `u16` + range attr
        assert!(matches!(dp["port"].field_type, FieldType::Integer));
        assert_eq!(dp["port"].constraints.len(), 2, "port should carry Min+Max");

        // doc comments survive as descriptions
        assert!(!dp["path"].description.is_empty());
        // required set: path + port (protocol/label have serde defaults)
        assert!(dp["path"].required && dp["port"].required);
        assert!(!dp["protocol"].required && !dp["label"].required);
    }

    #[test]
    fn should_bind_and_unbind_declared_sockets() {
        let dir = tempfile::tempdir().expect("tempdir");
        let plugin = UnixSocketPlugin::new();

        let ep = endpoint(dir.path(), "qdrant.sock", 6334);
        let desired = UnixSocketState {
            sockets: vec![ep.clone()],
        };

        let result = plugin.reconcile(&desired);
        assert!(result.success, "errors: {:?}", result.errors);
        assert!(std::path::Path::new(&ep.path).exists());
        assert!(plugin.active.lock().contains_key(&ep.path));

        // Reconciling to an empty set tears the socket down.
        let cleared = plugin.reconcile(&UnixSocketState::default());
        assert!(cleared.success);
        assert!(!std::path::Path::new(&ep.path).exists());
        assert!(plugin.active.lock().is_empty());
    }

    #[test]
    fn should_be_idempotent_for_already_bound_sockets() {
        let dir = tempfile::tempdir().expect("tempdir");
        let plugin = UnixSocketPlugin::new();
        let desired = UnixSocketState {
            sockets: vec![
                endpoint(dir.path(), "a.sock", 1),
                endpoint(dir.path(), "b.sock", 2),
            ],
        };

        let first = plugin.reconcile(&desired);
        assert_eq!(first.changes_applied.len(), 2);

        // Second reconcile against the same desired set creates nothing new.
        let second = plugin.reconcile(&desired);
        assert!(second.changes_applied.is_empty());
        assert_eq!(plugin.active.lock().len(), 2);
    }
}

/// Frozen golden reference: the original hand-rolled schema, kept **test-only**
/// so `derived_schema_matches_hand_rolled` can prove the derived schema still
/// matches the contract this plugin shipped with. Production uses
/// [`unix_socket_schema_derived`].
#[cfg(test)]
pub(crate) fn unix_socket_schema() -> PluginSchema {
    let mut socket_fields = HashMap::new();
    socket_fields.insert(
        "path".to_string(),
        FieldSchema {
            field_type: FieldType::String,
            required: true,
            description: "Filesystem path of the unix domain socket".to_string(),
            default: None,
            example: Some(json!("/run/qdrant.sock")),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    socket_fields.insert(
        "port".to_string(),
        FieldSchema {
            field_type: FieldType::Integer,
            required: true,
            description: "Local TCP port xray listens on and proxies into this socket".to_string(),
            default: None,
            example: Some(json!(6334)),
            constraints: vec![
                Constraint::Min { value: 1.0 },
                Constraint::Max { value: 65535.0 },
            ],
            read_only: false,
            read_only_when: None,
        },
    );
    socket_fields.insert(
        "protocol".to_string(),
        FieldSchema {
            field_type: FieldType::String,
            required: false,
            description: "Transport protocol carried over the socket (grpc, jsonrpc, …)"
                .to_string(),
            default: Some(json!("grpc")),
            example: None,
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );
    socket_fields.insert(
        "label".to_string(),
        FieldSchema {
            field_type: FieldType::String,
            required: false,
            description: "Human-readable service label used as the xray outbound tag".to_string(),
            default: None,
            example: Some(json!("qdrant-grpc")),
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        },
    );

    PluginSchema::builder("unix_socket")
        .version("1.0.0")
        .description("Unix domain socket endpoints proxied into xray outbounds")
        .array_field(
            "sockets",
            FieldType::Object(socket_fields),
            true,
            "Declared unix socket endpoints",
        )
        .example(json!({
            "sockets": [
                {
                    "path": "/run/qdrant.sock",
                    "port": 6334,
                    "protocol": "grpc",
                    "label": "qdrant-grpc"
                },
                {
                    "path": "/run/netmaker/api.sock",
                    "port": 8081,
                    "protocol": "http",
                    "label": "netmaker-api"
                },
                {
                    "path": "/run/netmaker/mq.sock",
                    "port": 1883,
                    "protocol": "mqtt",
                    "label": "netmaker-mqtt"
                },
                {
                    "path": "/run/netmaker/mqtts.sock",
                    "port": 8883,
                    "protocol": "mqtt",
                    "label": "netmaker-mqtts"
                },
                {
                    "path": "/run/netmaker/ui.sock",
                    "port": 80,
                    "protocol": "http",
                    "label": "netmaker-ui"
                }
            ]
        }))
        .build()
}

//! Derive plugin schemas from `#[derive(schemars::JsonSchema)]` structs instead
//! of hand-building `FieldSchema` maps. This is the **standard** for new plugins
//! (see `docs/schema-from-structs.md`); existing plugins migrate as their config
//! structs get fully typed.
//!
//! The adapter walks the *JSON* of the derived schema rather than schemars'
//! typed API, so it stays robust across schemars 0.8/1.0 and decoupled — a
//! plugin only needs `serde_json::to_value(schemars::schema_for!(T))`.
//!
//! Before (hand-rolled, ~80 lines/plugin, drifts from the struct):
//! ```ignore
//! let mut socket_fields = HashMap::new();
//! socket_fields.insert("path".into(), FieldSchema { field_type: String, required: true, .. });
//! socket_fields.insert("port".into(), FieldSchema {
//!     field_type: Integer,
//!     constraints: vec![Constraint::Min{1.0}, Constraint::Max{65535.0}], .. });
//! PluginSchema::builder("unix_socket").array_field("sockets", Object(socket_fields), ..)
//! ```
//!
//! After (the struct *is* the schema):
//! ```ignore
//! #[derive(Serialize, Deserialize, schemars::JsonSchema)]
//! struct SocketEndpoint {
//!     /// doc comment → field description
//!     path: String,
//!     #[schemars(range(min = 1, max = 65535))] port: u16,
//!     ..
//! }
//! plugin_schema_from_json("unix_socket", "1.0.0", DESC,
//!     &serde_json::to_value(schemars::schema_for!(UnixSocketState)).unwrap())
//! ```

use op_state_store::{Constraint, FieldSchema, FieldType, PluginSchema};
use serde_json::{Map, Value as JVal};
use simd_json::OwnedValue;
use std::collections::{HashMap, HashSet};

/// Build a `PluginSchema` from the JSON of a schemars-derived schema.
///
/// The root type's top-level properties become the plugin's `fields`; `$ref`s
/// into `$defs`/`definitions` are resolved inline so nested structs (e.g. the
/// `SocketEndpoint` inside `sockets: Vec<SocketEndpoint>`) expand correctly.
pub fn plugin_schema_from_json(
    name: &str,
    version: &str,
    description: &str,
    root: &JVal,
) -> PluginSchema {
    let defs = root
        .get("$defs")
        .or_else(|| root.get("definitions"))
        .and_then(JVal::as_object);

    let top = resolve(root, defs);
    let required = required_set(top);

    let mut fields = HashMap::new();
    let mut subids = HashMap::new();
    if let Some(props) = top.get("properties").and_then(JVal::as_object) {
        for (fname, fnode) in props {
            let req = required.contains(fname.as_str());
            fields.insert(fname.clone(), field_schema(fnode, defs, req));
            if let Some(subid) = fnode.get("x-oscal-subid").and_then(JVal::as_str) {
                subids.insert(fname.clone(), subid.to_string());
            }
        }
    }

    // Root-level `#[schemars(extend("x-oscal-subid" = ...))]` → reserved key.
    if let Some(subid) = root.get("x-oscal-subid").and_then(JVal::as_str) {
        subids.insert("__schema__".to_string(), subid.to_string());
    }

    let mut schema = PluginSchema::builder(name)
        .version(version)
        .description(description)
        .build();
    schema.fields = fields;
    schema.subids = subids;
    // Struct-level `#[schemars(extend("x-immutable-paths" = [...]))]` → immutable_paths.
    if let Some(paths) = root.get("x-immutable-paths").and_then(JVal::as_array) {
        schema.immutable_paths = paths
            .iter()
            .filter_map(|v| v.as_str().map(String::from))
            .collect();
    }
    schema
}

/// Follow a single `$ref` into `$defs`/`definitions`, recursively.
fn resolve<'a>(node: &'a JVal, defs: Option<&'a Map<String, JVal>>) -> &'a JVal {
    if let (Some(r), Some(d)) = (node.get("$ref").and_then(JVal::as_str), defs) {
        if let Some(key) = r.rsplit('/').next() {
            if let Some(target) = d.get(key) {
                return resolve(target, defs);
            }
        }
    }
    node
}

fn required_set(node: &JVal) -> HashSet<String> {
    node.get("required")
        .and_then(JVal::as_array)
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(String::from))
                .collect()
        })
        .unwrap_or_default()
}

fn field_type(node: &JVal, defs: Option<&Map<String, JVal>>) -> FieldType {
    let node = resolve(node, defs);

    if let Some(en) = node.get("enum").and_then(JVal::as_array) {
        return FieldType::Enum(
            en.iter()
                .filter_map(|v| v.as_str().map(String::from))
                .collect(),
        );
    }

    match type_str(node) {
        Some("string") => FieldType::String,
        Some("integer") => FieldType::Integer,
        Some("number") => FieldType::Float,
        Some("boolean") => FieldType::Boolean,
        Some("array") => {
            let item = node
                .get("items")
                .map(|i| field_type(i, defs))
                .unwrap_or(FieldType::Any);
            FieldType::Array(Box::new(item))
        }
        Some("object") => {
            let req = required_set(node);
            let mut m = HashMap::new();
            if let Some(props) = node.get("properties").and_then(JVal::as_object) {
                for (k, v) in props {
                    m.insert(k.clone(), field_schema(v, defs, req.contains(k.as_str())));
                }
            }
            FieldType::Object(m)
        }
        _ => FieldType::Any,
    }
}

/// schemars emits `"type": "string"` or, for `Option<T>`, `"type": ["string","null"]`.
/// Collapse to the first non-null type.
fn type_str(node: &JVal) -> Option<&str> {
    match node.get("type") {
        Some(JVal::String(s)) => Some(s.as_str()),
        Some(JVal::Array(a)) => a.iter().filter_map(JVal::as_str).find(|t| *t != "null"),
        _ => None,
    }
}

fn field_schema(node: &JVal, defs: Option<&Map<String, JVal>>, required: bool) -> FieldSchema {
    let meta = resolve(node, defs);
    FieldSchema {
        field_type: field_type(node, defs),
        required,
        description: meta
            .get("description")
            .and_then(JVal::as_str)
            .unwrap_or_default()
            .to_string(),
        default: meta.get("default").map(to_simd),
        example: example_of(meta).map(to_simd),
        constraints: constraints(meta),
        read_only: meta
            .get("readOnly")
            .and_then(JVal::as_bool)
            .unwrap_or(false),
        read_only_when: None,
    }
}

fn example_of(node: &JVal) -> Option<&JVal> {
    if let Some(first) = node
        .get("examples")
        .and_then(JVal::as_array)
        .and_then(|a| a.first())
    {
        return Some(first);
    }
    node.get("example")
}

fn constraints(node: &JVal) -> Vec<Constraint> {
    let mut out = Vec::new();
    if let Some(m) = node.get("minimum").and_then(JVal::as_f64) {
        out.push(Constraint::Min { value: m });
    }
    if let Some(m) = node.get("maximum").and_then(JVal::as_f64) {
        out.push(Constraint::Max { value: m });
    }
    if let Some(p) = node.get("pattern").and_then(JVal::as_str) {
        out.push(Constraint::Pattern {
            regex: p.to_string(),
        });
    }
    out
}

/// `serde_json::Value` → `simd_json::OwnedValue` (the `Value` op_state_store uses).
fn to_simd(v: &JVal) -> OwnedValue {
    let mut bytes = serde_json::to_vec(v).unwrap_or_default();
    simd_json::to_owned_value(&mut bytes).unwrap_or_else(|_| simd_json::json!(null))
}

/// Test-only **full-fidelity** diff: lists every way `derived` departs from the
/// golden hand-rolled `reference` — field set, recursive types, `required`,
/// descriptions, defaults, examples, constraints, `read_only`, immutable paths,
/// and OSCAL subids at every nesting level.
/// Empty result ⇒ the derived schema reproduces the reference exactly. Any entry
/// must be consciously resolved (annotate the struct to preserve it, or document
/// it as a deliberate correction of a hand-rolled bug).
#[cfg(test)]
pub(crate) fn schema_diffs(reference: &PluginSchema, derived: &PluginSchema) -> Vec<String> {
    let mut d = Vec::new();
    if reference.name != derived.name {
        d.push(format!("name: {:?} -> {:?}", reference.name, derived.name));
    }
    if reference.version != derived.version {
        d.push(format!(
            "version: {:?} -> {:?}",
            reference.version, derived.version
        ));
    }
    if reference.description != derived.description {
        d.push(format!(
            "description: {:?} -> {:?}",
            reference.description, derived.description
        ));
    }
    let (mut ir, mut id) = (
        reference.immutable_paths.clone(),
        derived.immutable_paths.clone(),
    );
    ir.sort();
    id.sort();
    if ir != id {
        d.push(format!("immutable_paths: {ir:?} -> {id:?}"));
    }
    if reference.subids != derived.subids {
        d.push(format!(
            "subids: {:?} -> {:?}",
            reference.subids, derived.subids
        ));
    }
    let keys: std::collections::BTreeSet<&String> = reference
        .fields
        .keys()
        .chain(derived.fields.keys())
        .collect();
    for k in keys {
        match (reference.fields.get(k), derived.fields.get(k)) {
            (Some(r), Some(v)) => field_diffs(&mut d, k, r, v),
            (Some(_), None) => d.push(format!("{k}: DROPPED (in reference, not derived)")),
            (None, Some(_)) => d.push(format!("{k}: ADDED (in derived, not reference)")),
            (None, None) => {}
        }
    }
    d
}

#[cfg(test)]
fn field_diffs(d: &mut Vec<String>, prefix: &str, r: &FieldSchema, v: &FieldSchema) {
    if type_tag(&r.field_type) != type_tag(&v.field_type) {
        d.push(format!(
            "{prefix}.type: {} -> {}",
            type_tag(&r.field_type),
            type_tag(&v.field_type)
        ));
    }
    if r.required != v.required {
        d.push(format!(
            "{prefix}.required: {} -> {}",
            r.required, v.required
        ));
    }
    if r.description != v.description {
        d.push(format!(
            "{prefix}.description: {:?} -> {:?}",
            r.description, v.description
        ));
    }
    if val_str(&r.default) != val_str(&v.default) {
        d.push(format!(
            "{prefix}.default: {} -> {}",
            val_str(&r.default),
            val_str(&v.default)
        ));
    }
    if val_str(&r.example) != val_str(&v.example) {
        d.push(format!(
            "{prefix}.example: {} -> {}",
            val_str(&r.example),
            val_str(&v.example)
        ));
    }
    if constraint_tags(&r.constraints) != constraint_tags(&v.constraints) {
        d.push(format!(
            "{prefix}.constraints: {:?} -> {:?}",
            constraint_tags(&r.constraints),
            constraint_tags(&v.constraints)
        ));
    }
    if r.read_only != v.read_only {
        d.push(format!(
            "{prefix}.read_only: {} -> {}",
            r.read_only, v.read_only
        ));
    }

    // Recurse into nested container types so nested field-level diffs are reported.
    field_type_diffs(d, prefix, &r.field_type, &v.field_type);
}

#[cfg(test)]
fn field_type_diffs(d: &mut Vec<String>, prefix: &str, r: &FieldType, v: &FieldType) {
    match (r, v) {
        (FieldType::Array(r_inner), FieldType::Array(v_inner)) => {
            field_type_diffs(d, &format!("{prefix}[]"), r_inner, v_inner);
        }
        (FieldType::Object(r_map), FieldType::Object(v_map)) => {
            let keys: std::collections::BTreeSet<&String> =
                r_map.keys().chain(v_map.keys()).collect();
            for k in keys {
                match (r_map.get(k), v_map.get(k)) {
                    (Some(rf), Some(vf)) => field_diffs(d, &format!("{prefix}.{k}"), rf, vf),
                    (Some(_), None) => {
                        d.push(format!("{prefix}.{k}: DROPPED (in reference, not derived)"))
                    }
                    (None, Some(_)) => {
                        d.push(format!("{prefix}.{k}: ADDED (in derived, not reference)"))
                    }
                    (None, None) => {}
                }
            }
        }
        _ => {}
    }
}

#[cfg(test)]
fn val_str(v: &Option<OwnedValue>) -> String {
    match v {
        Some(x) => format!("{x:?}"),
        None => "∅".into(),
    }
}

#[cfg(test)]
fn type_tag(t: &FieldType) -> String {
    match t {
        FieldType::String => "string".into(),
        FieldType::Integer => "integer".into(),
        FieldType::Float => "float".into(),
        FieldType::Boolean => "boolean".into(),
        FieldType::Any => "any".into(),
        FieldType::Enum(_) => "enum".into(),
        FieldType::Array(i) => format!("array<{}>", type_tag(i)),
        FieldType::Object(m) => {
            let mut entries: Vec<String> = m
                .iter()
                .map(|(k, v)| format!("{k}:{}", type_tag(&v.field_type)))
                .collect();
            entries.sort();
            format!("object{{{}}}", entries.join(","))
        }
    }
}

#[cfg(test)]
fn constraint_tags(cs: &[Constraint]) -> Vec<String> {
    let mut v: Vec<String> = cs
        .iter()
        .map(|c| match c {
            Constraint::Min { value } => format!("min:{value}"),
            Constraint::Max { value } => format!("max:{value}"),
            Constraint::Pattern { regex } => format!("pattern:{regex}"),
            Constraint::OneOf { .. } => "oneof".into(),
            Constraint::RequiresField { field } => format!("requires:{field}"),
            Constraint::Custom { validator } => format!("custom:{validator}"),
        })
        .collect();
    v.sort();
    v
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::state_plugins::common::oscal::validate_subid;

    #[test]
    fn walks_array_of_objects_with_constraints() {
        // Minimal hand-written JSON mirroring what schemars derives for
        // `UnixSocketState { sockets: Vec<SocketEndpoint> }`.
        let bytes = br##"{
            "type":"object",
            "properties":{"sockets":{"type":"array","description":"Declared endpoints",
                "items":{"$ref":"#/$defs/SocketEndpoint"}}},
            "required":["sockets"],
            "$defs":{"SocketEndpoint":{"type":"object",
                "properties":{
                    "path":{"type":"string","description":"socket path"},
                    "port":{"type":"integer","minimum":1,"maximum":65535}},
                "required":["path","port"]}}
        }"##
        .to_vec();
        let root: JVal = serde_json::from_slice(&bytes).unwrap();
        let s = plugin_schema_from_json("unix_socket", "1.0.0", "desc", &root);

        let sockets = s.fields.get("sockets").expect("sockets field");
        assert!(sockets.required);
        match &sockets.field_type {
            FieldType::Array(inner) => match inner.as_ref() {
                FieldType::Object(props) => {
                    assert!(props.contains_key("path"));
                    let port = props.get("port").unwrap();
                    assert!(port.required);
                    assert_eq!(port.constraints.len(), 2); // Min + Max
                }
                other => panic!("expected object items, got {other:?}"),
            },
            other => panic!("expected array, got {other:?}"),
        }
    }

    #[test]
    fn derived_schema_matches_hand_rolled_for_unix_socket() {
        let hand = crate::state_plugins::unix_socket::unix_socket_schema();
        let derived = crate::state_plugins::unix_socket::unix_socket_schema_derived();
        let diffs = schema_diffs(&hand, &derived);
        assert!(diffs.is_empty(), "schema_diffs: {:#?}", diffs);
    }

    #[test]
    fn reports_nested_mismatch() {
        let hand = plugin_schema_from_json(
            "nested_test",
            "1.0.0",
            "desc",
            &serde_json::json!({
                "type": "object",
                "properties": {
                    "wrapper": {
                        "type": "object",
                        "properties": {
                            "inner": { "type": "string", "description": "inner field" }
                        },
                        "required": ["inner"]
                    }
                },
                "required": ["wrapper"]
            }),
        );
        let derived = plugin_schema_from_json(
            "nested_test",
            "1.0.0",
            "desc",
            &serde_json::json!({
                "type": "object",
                "properties": {
                    "wrapper": {
                        "type": "object",
                        "properties": {
                            "inner": { "type": "integer", "description": "inner field" }
                        },
                        "required": ["inner"]
                    }
                },
                "required": ["wrapper"]
            }),
        );
        let diffs = schema_diffs(&hand, &derived);
        assert!(
            !diffs.is_empty(),
            "expected a non-empty diff for nested mismatch"
        );
        assert!(
            diffs
                .iter()
                .any(|d| d.contains("wrapper.inner") && d.contains("type")),
            "expected nested inner.type diff, got: {:#?}",
            diffs
        );
    }

    #[test]
    fn ingests_root_and_field_subids() {
        let schema = plugin_schema_from_json(
            "subid_test",
            "1.0.0",
            "desc",
            &serde_json::json!({
                "type": "object",
                "x-oscal-subid": "sch.software.test-schema.describe@v1",
                "properties": {
                    "field_a": {
                        "type": "string",
                        "x-oscal-subid": "exp.software.test-field.render@v1"
                    }
                },
                "required": ["field_a"]
            }),
        );
        assert_eq!(
            schema.subids.get("__schema__"),
            Some(&"sch.software.test-schema.describe@v1".to_string())
        );
        assert_eq!(
            schema.subids.get("field_a"),
            Some(&"exp.software.test-field.render@v1".to_string())
        );
    }

    #[test]
    fn validate_subid_accepts_valid_and_rejects_invalid() {
        assert!(validate_subid("mut.service.state-sync.apply-patch@v1").is_ok());
        assert!(validate_subid("exp.software.cognitive-memory.render").is_ok());
        assert!(validate_subid("obs.service.plugin-projection.query").is_ok());
        assert!(validate_subid("bad-category.software.foo.bar").is_err());
        assert!(validate_subid("mut.bad-type.foo.bar").is_err());
        assert!(validate_subid("mut.software.foo").is_err());
    }
